var YIJING_HEXAGRAMS=[{num:1,name:"Càn",upper:"Càn",lower:"Càn",verdict:"cat",guaci:"Trời cao rộng lớn, vạn vật hanh thông, giữ đức cương trực ắt thành việc.",tuong:"Trời lồng bóng trời, sức mạnh vô cùng, người quân tử tự cường không ngơi nghỉ.",giai:"Thời vận hanh thông, gặp nhiều thuận lợi để khởi sự. Nên giữ tâm chính trực, hành động vững vàng và không kiêu ngạo.",lines:["Sơ Cửu: Rồng còn ẩn dưới vực sâu, chớ nên vội vàng manh động.","Cửu Nhị: Rồng hiện giữa đồng bao la, gặp thời mở lối nên tìm người hiền tài.","Cửu Tam: Suốt ngày chăm chỉ siêng năng, đêm về suy ngẫm giữ lòng cẩn trọng.","Cửu Tứ: Có lúc nhảy vọt qua đầm, tùy cơ ứng biến không sợ lỡ bước.","Cửu Ngũ: Rồng bay lượn giữa trời mây, thời cơ rực rỡ thỏa sức vẫy vùng.","Thượng Cửu: Lên quá cao ắt hối tiếc, biết điểm dừng mới giữ được an vui."]},{num:2,name:"Khôn",upper:"Khôn",lower:"Khôn",verdict:"cat",guaci:"Đất dày chở che vạn vật, mềm mỏng thuận hòa thì được lợi lâu dài.",tuong:"Đất rộng ôm lấy muôn loài, người biết dung chứa thì phúc đức sâu dày.",giai:"Nên theo sau chớ đứng đầu, lấy mềm thắng cứng sẽ đạt bình an. Việc đời thuận hòa, ứng xử khéo léo ắt hưởng quả ngọt.",lines:["Sơ Lục: Bước chân đạp sương lạnh buốt, biết mùa băng giá đang dần tới gần.","Lục Nhị: Thẳng thắn vuông tròn đức độ, chẳng cần tính toán mà việc tự nên.","Lục Tam: Khéo giấu tài năng vào trong, đợi khi thời đến mới trọn phận mình.","Lục Tứ: Buộc kín miệng túi giữ lời, kín kẽ dè dặt tránh xa lỗi lầm.","Lục Ngũ: Áo vàng giản dị đoan trang, khiêm nhường đứng giữa hưởng trọn an lành.","Thượng Lục: Cương âm đấu với dương cùng, tranh chấp gay gắt chuốc lấy thương đau."]},{num:3,name:"Truân",upper:"Khảm",lower:"Chấn",verdict:"hung",guaci:"Mầm non nảy nở giữa gian nan, vạn sự khởi đầu chớ vội tiến bước.",tuong:"Mây nước cuộn sấm rền vang, cây cỏ mới nhú còn nhiều chông gai.",giai:"Khởi đầu gặp nhiều trắc trở, mọi việc chưa thuận buồm xuôi gió. Cần kiên nhẫn tích lũy nội lực, tìm kiếm trợ lực và chớ nôn nóng.",lines:["Sơ Cửu: Đá tảng chắn lối dừng chân, giữ lòng ngay thẳng tìm người cậy trông.","Lục Nhị: Khó khăn dùng dằng bước đi, giữ lòng son sắt mười năm đợi thời.","Lục Tam: Đuổi hươu không người dẫn đường, lạc vào rừng rậm chi bằng dừng chân.","Lục Tứ: Ngựa xe ngập ngừng tìm bạn, nếu biết hòa hợp thì tiến sẽ lành.","Cửu Ngũ: Ban ơn nhỏ giọt chưa sâu, việc nhỏ thì được việc lớn chớ vội.","Thượng Lục: Ngựa xe rời rạc xót xa, nước mắt đầm đìa than vãn chẳng nguôi."]},{num:4,name:"Mông",upper:"Cấn",lower:"Khảm",verdict:"hung",guaci:"Mông muội cần người chỉ bảo, cầu học chân thành thì trí sáng lòng trong.",tuong:"Dưới chân núi suối reo tuôn, suối nguồn mờ mịt chưa rõ lối ra.",giai:"Thời điểm còn mù mờ thiếu thông tin, dễ vấp ngã vì thiếu kinh nghiệm. Hãy lắng nghe người đi trước chỉ dẫn, học hỏi khiêm tốn rồi mới hành động.",lines:["Sơ Lục: Khai mở trí tuệ ban đầu, kỷ luật rèn giũa để tránh tai ương.","Cửu Nhị: Bao dung đón nhận trò khờ, gia đình hòa thuận vạn sự yên vui.","Lục Tam: Thấy người sang vội đổi lòng, không giữ tiết hạnh chuốc lấy dèm pha.","Lục Tứ: Bế tắc trong vòng u tối, cô độc khép kín chuốc lấy muộn phiền.","Lục Ngũ: Trẻ thơ ngây ngô học lễ, khiêm nhường nghe dạy ắt gặp điều lành.","Thượng Cửu: Nghiêm khắc sửa trị lầm lỗi, phòng ngừa tai họa chớ nên hại người."]},{num:5,name:"Nhu",upper:"Khảm",lower:"Càn",verdict:"trung",guaci:"Mây tụ trời cao chờ mưa đổ, giữ lòng kiên nhẫn ăn uống đợi thời.",tuong:"Mây nước ngút ngàn trên trời, người thức thời thong thả dưỡng sức nuôi tâm.",giai:"Phía trước có nguy hiểm trở ngại, tiến gấp dễ hỏng việc. Hãy bình tĩnh chờ thời cơ chín muồi, bồi dưỡng sức khỏe và tinh thần.",lines:["Sơ Cửu: Chờ đợi nơi bãi đất hoang, giữ yên bổn phận không mắc lỗi lầm.","Cửu Nhị: Chờ đợi nơi cồn cát xa, có lời qua tiếng lại nhưng cuối cùng yên.","Cửu Tam: Chờ đợi trong chốn bùn lầy, sơ suất sơ hở giặc tìm đến nơi.","Lục Tứ: Chờ đợi nơi hố máu sâu, bình tĩnh né tránh thoát khỏi hiểm nguy.","Cửu Ngũ: Chờ đợi bên mâm rượu nồng, lòng vui thanh thản điềm lành kề bên.","Thượng Lục: Ba khách không mời tự đến, kính cẩn tiếp đãi ắt hóa cát tường."]},{num:6,name:"Tụng",upper:"Càn",lower:"Khảm",verdict:"hung",guaci:"Tranh chấp kiện tụng chẳng lành, dừng bước hòa giải giữ lấy bình yên.",tuong:"Trời lên cao nước chảy xuống, đôi đường trái nghịch sinh sự cãi cọ.",giai:"Dễ nảy sinh bất đồng, mâu thuẫn trong các mối quan hệ hay công việc. Nên dĩ hòa vi quý, nhường nhịn một bước để tránh hao tổn tâm lực.",lines:["Sơ Lục: Chuyện tranh cãi chớ kéo dài, chịu chút tai tiếng rồi việc sẽ êm.","Cửu Nhị: Tranh cãi không lại thì lui, về làng ẩn phận tránh được tai bay.","Lục Tam: Ăn nhờ đức cũ tiền nhân, giữ trọn phận mình dẫu nguy chẳng hại.","Cửu Tứ: Tranh cãi không thành quay về, đổi dạ theo phải đổi ý an thân.","Cửu Ngũ: Đứng giữa phân giải công bằng, sự việc sáng rõ nhận lấy điều lành.","Thượng Cửu: Có được đai gấm vinh phong, trong một buổi sáng ba lần tước đi."]},{num:7,name:"Sư",upper:"Khôn",lower:"Khảm",verdict:"trung",guaci:"Đem quân chinh chiến vì việc nghĩa, tướng già cầm quyền mới giữ được an.",tuong:"Trong lòng đất chứa nguồn nước, người quân tử nuôi dưỡng lòng dân.",giai:"Đang gánh vác trách nhiệm nặng nề hoặc bước vào cuộc đua tranh cam go. Cần giữ nghiêm kỷ luật, chọn người tài đức chỉ huy và thận trọng từng bước.",lines:["Sơ Lục: Xuất quân cần có kỷ cương, làm trái phép tắc rước họa vào thân.","Cửu Nhị: Ở giữa hàng quân chỉ huy, ba lần được thưởng giữ lòng trung trinh.","Lục Tam: Quân tướng chở xác xe tang, kỷ cương lỏng lẻo chịu cảnh bại lui.","Lục Tứ: Tạm lui quân về đóng giữ, biết tạm dừng bước không mắc lỗi lầm.","Lục Ngũ: Chim muông vào phá mùa màng, giao cho người giỏi chớ để kẻ hèn.","Thượng Lục: Vua phong thưởng kẻ công thần, chớ dùng kẻ tiểu nhân làm loạn nước."]},{num:8,name:"Tỷ",upper:"Khảm",lower:"Khôn",verdict:"cat",guaci:"Thân ái gần gũi giúp đỡ nhau, thành tâm kết bạn thì vạn sự an.",tuong:"Nước chảy liền trên mặt đất, muôn vật gắn kết hòa thuận bên nhau.",giai:"Thời vận tương trợ, gặp được quý nhân hoặc bạn bè đồng lòng. Hãy mở rộng tấm lòng, cư xử chân thành và biết chọn bạn mà chơi.",lines:["Sơ Lục: Chân thành kết thân từ đầu, bình gốm đựng nước chẳng sợ lỗi chi.","Lục Nhị: Kết giao xuất phát tự lòng, giữ đạo ngay thẳng gặp điềm cát tường.","Lục Tam: Kết thân lầm kẻ xấu xa, chuốc lấy đau buồn hối hận về sau.","Lục Tứ: Kết giao với bậc bề trên, thành kính một lòng gặp điều may mắn.","Cửu Ngũ: Lưới vây ba mặt thả một, người tự tìm đến phúc lộc đầy nhà.","Thượng Lục: Kết thân không có chỗ dựa, không đầu không mối kết cục dở dang."]},{num:9,name:"Tiểu Súc",upper:"Tốn",lower:"Càn",verdict:"trung",guaci:"Tích lũy nhỏ bé chờ ngày lớn, mây dày đặc mà mưa chưa tuôn rơi.",tuong:"Gió lượn trên nền trời cao, tích tụ văn vẻ rèn luyện đức tài.",giai:"Năng lực tích tụ chưa đủ để làm việc lớn, chớ nên nóng vội bứt phá. Nên kiên trì vun vén từ việc nhỏ, tu dưỡng bản thân và đợi thời cơ.",lines:["Sơ Cửu: Quay về nẻo cũ của mình, giữ yên phận định không mắc sai lầm.","Cửu Nhị: Dắt tay cùng nhau quay về, đường ngay bước tiếp không lo tai ương.","Cửu Tam: Bánh xe tuột khỏi trục xe, vợ chồng bất hòa mắt nhìn hờn ghen.","Lục Tứ: Giữ lòng chân thành thẳng ngay, máu tan sợ hết hiểm nguy lùi dần.","Cửu Ngũ: Thành tâm chia sẻ cùng người, liên kết láng giềng nhân đôi niềm vui.","Thượng Cửu: Mưa rơi nước đọng đã đầy, biết dừng đúng lúc giữ trọn bình an."]},{num:10,name:"Lý",upper:"Càn",lower:"Đoài",verdict:"trung",guaci:"Dẫm lên đuôi cọp mà không cắn, giữ lễ khiêm cung ắt vượt hiểm nghèo.",tuong:"Trời ở trên đầm ở dưới, phân biệt thứ bậc định rõ lòng người.",giai:"Đang ở vào tình thế tế nhị, nhạy cảm hoặc đối diện cấp trên, người khó tính. Cần cư xử cẩn trọng, lễ độ, tuân thủ phép tắc thì bình an vô sự.",lines:["Sơ Cửu: Mộc mạc dạo bước đường quen, tự đi theo lối không ai trách phiền.","Cửu Nhị: Đi trên đường phẳng thênh thang, người ẩn dật yên lòng giữ tiết thanh cao.","Lục Tam: Mắt chột đòi nhìn cho xa, chân thọt đòi đi cọp cắn đau đớn.","Cửu Tứ: Dẫm phải đuôi cọp sợ run, cẩn thận từng bước cuối cùng tai qua.","Cửu Ngũ: Quyết đoán tiến bước kiên cường, dẫu có nguy nan giữ lòng chính trực.","Thượng Cửu: Nhìn lại đường đi đã qua, xem xét quả báo trọn vẹn phúc lành."]},{num:11,name:"Thái",upper:"Khôn",lower:"Càn",verdict:"cat",guaci:"Trời đất giao hòa vạn vật sinh, kẻ nhỏ ra đi người lớn tìm về.",tuong:"Trời đất giao cảm hòa hợp, muôn vật tốt tươi thái bình thịnh trị.",giai:"Vận may cực thịnh, công việc hanh thông, người hiền cùng chung tay hợp tác. Hãy tận dụng cơ hội để phát triển, nhưng nhớ giữ đức khiêm nhường.",lines:["Sơ Cửu: Nhổ cỏ rễ liền từng chùm, đồng lòng tiến bước đón nhận niềm vui.","Cửu Nhị: Bao dung tấm lòng rộng mở, qua sông không thuyền giữ đạo trung dung.","Cửu Tam: Chẳng có phẳng nào không dốc, chẳng có đi nào không lại, giữ lòng kiên định.","Lục Tứ: Nhẹ nhàng bay lượn tìm nhau, giàu nghèo không kể bạn bè chân phương.","Lục Ngũ: Đế Ất gả gái ban hôn, thuận hòa êm ấm hưởng trọn niềm vui.","Thượng Lục: Thành lũy sụp xuống rãnh sâu, chớ động binh đao hãy lo giữ mình."]},{num:12,name:"Bĩ",upper:"Càn",lower:"Khôn",verdict:"hung",guaci:"Trời đất cách trở không giao nhau, tiểu nhân hoành hành quân tử lánh mình.",tuong:"Trời ở trên cao đất ở dưới, cách biệt đôi bờ bế tắc không thông.",giai:"Thời vận bế tắc, hiểu lầm nảy sinh, mưu sự khó thành. Không nên gượng ép hay đầu tư mạo hiểm, hãy an phận thủ thường, giữ gìn đạo đức chờ thời.",lines:["Sơ Lục: Nhổ cụm cỏ tranh rễ liền, ẩn nhẫn giữ đạo không bước vào vòng danh lợi.","Lục Nhị: Thuận hòa nhẫn nhịn cho qua, kẻ tiểu nhân xa lánh người quân tử an lòng.","Lục Tam: Mang lấy nỗi nhục trong lòng, biết xấu hổ thì sửa mình tránh tai họa.","Cửu Tứ: Có mệnh bề trên trao ban, bạn bè đồng chí cùng hưởng ân lành.","Cửu Ngũ: Vận bĩ sắp qua hồi sinh, lo sợ tiêu vong như buộc gốc dâu già.","Thượng Cửu: Bế tắc đã đến ngày cùng, mây tan trời sáng vận may đổi dời."]},{num:13,name:"Đồng Nhân",upper:"Càn",lower:"Ly",verdict:"cat",guaci:"Hòa đồng cùng người giữa chốn đông, vượt qua sông lớn mưu sự ắt thành.",tuong:"Trời cùng với lửa rực sáng, quân tử phân biệt dòng họ hiểu rõ loài vật.",giai:"Đại cục hòa hợp, nhận được sự ủng hộ rộng rãi từ mọi người xung quanh. Nên làm việc tập thể, đối xử công bằng không thiên vị, việc ắt thành công.",lines:["Sơ Cửu: Ra cửa kết bạn hòa đồng, không tư lợi nhỏ chẳng mắc lỗi lầm.","Lục Nhị: Chỉ thân với kẻ trong họ, hạn hẹp tầm nhìn chuốc lấy chê bai.","Cửu Tam: Giấu quân trong bụi rậm rạp, lên đồi quan sát ba năm không đánh.","Cửu Tứ: Trèo lên tường thành ngóng trông, không đánh lại lui giữ được an toàn.","Cửu Ngũ: Trước thì khóc than đau đớn, sau lại cười vang hai người sum họp.","Thượng Cửu: Hòa đồng ở nơi ngoại ô, dẫu chưa thỏa chí nhưng lòng bình yên."]},{num:14,name:"Đại Hữu",upper:"Ly",lower:"Càn",verdict:"cat",guaci:"Sở hữu lớn lao chiếu sáng ngời, trời ban phúc lành vạn sự hanh thông.",tuong:"Lửa rực sáng trên tầng trời, quân tử ngăn điều ác giương cao điều lành.",giai:"Thời kỳ sung túc rực rỡ, uy tín và năng lực được khẳng định. Nên rộng lòng giúp đỡ mọi người, không xa hoa lãng phí để giữ phúc bền lâu.",lines:["Sơ Cửu: Không giao tiếp điều sai trái, tránh xa tổn hại giữ vẹn bình yên.","Cửu Nhị: Xe lớn chở nặng đi xa, có nơi để tới không lo đổ nhào.","Cửu Tam: Bậc công hầu dâng vua chúa, kẻ tiểu nhân làm ắt chuốc lấy vạ.","Cửu Tứ: Chẳng màng khoe khoang của cải, giữ mình khiêm tốn tai họa không vương.","Lục Ngũ: Lòng thành tín chiếu sáng xa, uy nghiêm đoan chính người người kính yêu.","Thượng Cửu: Được trời che chở giúp đỡ, vạn sự hanh thông không gì chẳng lợi."]},{num:15,name:"Khiêm",upper:"Khôn",lower:"Cấn",verdict:"cat",guaci:"Núi cao chịu nép dưới đất dày, người biết khiêm nhường ắt được trọn vẹn.",tuong:"Đất bao bọc núi bên trong, quân tử bớt chỗ nhiều bù vào chỗ ít.",giai:"Quẻ tốt nhất trong 64 quẻ, biểu trưng cho sự khiêm tốn và đức độ. Càng nhún nhường, biết nghĩ cho người khác thì phúc lộc càng đong đầy.",lines:["Sơ Lục: Khiêm tốn nhún nhường từ tâm, qua sông sâu rộng vẫn vượt bình an.","Lục Nhị: Tiếng khiêm lan tỏa xa gần, giữ lòng ngay thẳng hưởng trọn niềm vui.","Cửu Tam: Nhọc nhằn lập công giữ khiêm, người quân tử trọn đời được ngợi khen.","Lục Tứ: Phát huy đức khiêm đúng lúc, không gì không lợi tiến bước quang minh.","Lục Ngũ: Chẳng cậy giàu sang lấn lướt, dẹp yên kẻ nghịch lấy đức phục người.","Thượng Lục: Khiêm tốn vang danh khắp chốn, đem quân rèn giũa sửa trị cõi riêng."]},{num:16,name:"Dự",upper:"Chấn",lower:"Khôn",verdict:"cat",guaci:"Sấm động đất trời vui hân hoan, lòng người phấn chấn ra quân lập công.",tuong:"Sấm vang trên mặt đất bằng, người xưa làm nhạc tế lễ thần linh.",giai:"Không khí vui tươi phấn khởi, tinh thần thoải mái gặp nhiều cơ hội. Tuy nhiên cần vui vẻ chừng mực, phòng xa biến cố để niềm vui được trọn vẹn.",lines:["Sơ Lục: Vội vàng khoe khoang niềm vui, chí khí nông cạn rước họa vào thân.","Lục Nhị: Vững như bàn đá kiên cố, chẳng đợi hết ngày biết trước việc sắp đến.","Lục Tam: Ngước nhìn chờ mong kẻ khác, dùng dằng chậm trễ chuốc lấy tiếc nuối.","Cửu Tứ: Khơi nguồn niềm vui cho đời, lòng thành kết bạn đại sự ắt thành.","Lục Ngũ: Mang bệnh dây dưa trong mình, giữ gìn tĩnh dưỡng chẳng đến nỗi nguy.","Thượng Lục: Mải mê chìm trong vui thú, biết hối cải sớm thoát khỏi lầm mê."]},{num:17,name:"Tùy",upper:"Đoài",lower:"Chấn",verdict:"cat",guaci:"Thuận theo lẽ trời tùy cơ ứng biến, giữ lòng thành thực ắt được hanh thông.",tuong:"Đầm nước có sấm động bên dưới, người thức thời biết tùy thời mà nghỉ ngơi dưỡng sức.",giai:"Thời vận chuyển mình thuận lợi khi biết thích ứng linh hoạt với hoàn cảnh. Cư xử mềm mỏng, lắng nghe tập thể sẽ gặt hái kết quả tốt đẹp.",lines:["Sơ Cửu: Chuyển đổi ý định bước ra ngoài kết giao, gặp gỡ bạn bè việc sẽ thành.","Lục Nhị: Bám víu việc nhỏ bỏ quên chí lớn, tham gần bỏ xa chuốc lấy tiếc nuối.","Lục Tam: Buông chuyện vặt vãnh theo người tài đức, cầu việc chính đáng được toại nguyện.","Cửu Tứ: Theo đuổi tư lợi dính việc thị phi, giữ tâm ngay thẳng mới khỏi tai ương.","Cửu Ngũ: Lòng thành hướng thiện gặp người tri kỷ, niềm vui chan hòa khắp chốn.","Thượng Lục: Nghĩa tình gắn bó keo sơn bền chặt, chân thành sắt son trọn vẹn trước sau."]},{num:18,name:"Cổ",upper:"Cấn",lower:"Tốn",verdict:"trung",guaci:"Việc cũ đình trệ cần sửa sang, trước sau tính kỹ ắt vượt khó khăn.",tuong:"Gió lượn thổi quanh chân núi, người quân tử chấn hưng chí khí bồi dưỡng đức hạnh.",giai:"Tình thế tồn đọng nhiều vướng mắc từ trước, cần quyết tâm chấn chỉnh và làm mới. Thận trọng rà soát nguyên nhân, không né tránh thì mọi việc dần khởi sắc.",lines:["Sơ Lục: Nối nghiệp việc cha gánh vác việc nhà, khéo sửa sai lầm không lo mang tiếng.","Cửu Nhị: Chỉnh đốn việc mẹ giữ lòng mềm mỏng, tránh sự gay gắt chuốc lấy muộn phiền.","Cửu Tam: Sửa việc của cha dẫu có nóng vội, đôi chút hối tiếc chẳng mắc lỗi to.","Lục Tứ: Khoan dung việc cũ để sinh bê trễ, nếu không thay đổi ắt gặp gian nan.","Lục Ngũ: Khéo léo sửa sang tàn dư việc trước, dùng đức cảm hóa tiếng thơm lưu truyền.","Thượng Cửu: Không màng danh lợi chẳng thờ vương hầu, giữ chí thanh cao an nhàn tự tại."]},{num:19,name:"Lâm",upper:"Khôn",lower:"Đoài",verdict:"cat",guaci:"Khí thế lớn mạnh tiến bước hanh thông, phòng xa suy biến để giữ phúc lành.",tuong:"Đất cao soi bóng đầm sâu, người quân tử dạy dỗ dân chúng chở che muôn phương.",giai:"Thời vận đang lên, sức ảnh hưởng mở rộng và nhiều cơ hội mới mở ra. Hãy chủ động hành động nhưng chớ chủ quan, biết lo xa khi đang thịnh mới bền vững.",lines:["Sơ Cửu: Cùng bạn đồng lòng tiến lên việc tốt, giữ trọn đạo ngay gặp điều cát tường.","Cửu Nhị: Khí thế hiên ngang cùng tiến một bước, vạn sự thuận hòa không điều gì ngại.","Lục Tam: Vừa mới đắc chí đã vội lơ là, biết lo hối cải tránh được rủi ro.","Lục Tứ: Thân hành đến chốn gần gũi chỉ bảo, công việc chu toàn chẳng mắc sai lầm.","Lục Ngũ: Sáng suốt cai trị tin dùng người hiền, vẹn cả đôi đường việc lớn ắt xuôi.","Thượng Lục: Đem lòng đôn hậu đối đãi cùng người, phúc đức trọn vẹn mọi sự an lành."]},{num:20,name:"Quan",upper:"Tốn",lower:"Khôn",verdict:"trung",guaci:"Rửa tay thanh sạch trước khi làm lễ, giữ lòng thành kính muôn người hướng theo.",tuong:"Gió thổi lướt trên mặt đất, người xưa đi khắp nơi xem xét dân tình.",giai:"Thời điểm thích hợp để quan sát, suy xét thấu đáo trước khi đưa ra quyết định. Nên lắng nghe học hỏi, giữ thái độ công tâm và tu dưỡng phẩm chất nội tại.",lines:["Sơ Lục: Nhìn đời hạn hẹp như mắt trẻ thơ, tầm nhìn thiển cận khó thành việc to.","Lục Nhị: Nhìn qua khe cửa thấy việc nửa vời, an phận giữ nhà tạm được bình yên.","Lục Tam: Nhìn lại bước đường của bản thân mình, biết tiến biết lui mới là phải phép.","Lục Tứ: Hiểu rõ nét đẹp phong tục nước nhà, xứng đáng làm khách nơi chốn quyền quý.","Cửu Ngũ: Tự soi xét lại hành vi của mình, người quân tử luôn không mắc lỗi lầm.","Thượng Cửu: Soi xét thiên hạ bằng tâm thanh tịnh, giữ trọn thanh danh quân tử an vui."]},{num:21,name:"Phệ Hạp",upper:"Ly",lower:"Chấn",verdict:"trung",guaci:"Cắn đứt vật cản làm rõ sự tình, giữ phép công bằng ắt việc hanh thông.",tuong:"Sấm chớp rền vang chiếu sáng đất trời, người phân xử minh bạch nghiêm minh thi hành pháp luật.",giai:"Đang có trở ngại hoặc bất đồng cản trở tiến trình, cần thẳng thắn giải quyết triệt để. Xử lý công việc dứt khoát, minh bạch và có lý có tình sẽ hóa giải vướng mắc.",lines:["Sơ Cửu: Chân mang cùm gỗ che mất ngón chân, răn dạy từ sớm tránh họa về sau.","Lục Nhị: Cắn miếng thịt mềm ngập mũi lúc nào, xử phạt đúng tội không ai trách phiền.","Lục Tam: Cắn miếng thịt khô gặp phải chất cay, có chút bực mình nhưng rồi tai qua.","Cửu Tứ: Cắn trúng xương khô tìm thấy mũi tên, gian nan bền chí cuối cùng tốt lành.","Lục Ngũ: Cắn miếng thịt khô nhặt được vàng ròng, giữ lòng công chính việc khó cũng xong.","Thượng Cửu: Đeo gông che tai chẳng nghe lời khuyên, ngoan cố bảo thủ chuốc họa vào thân."]},{num:22,name:"Bí",upper:"Cấn",lower:"Ly",verdict:"cat",guaci:"Trang điểm tao nhã làm đẹp sự việc, làm việc nhỏ thì hanh thông tốt lành.",tuong:"Dưới chân núi có ánh lửa bập bùng, quân tử làm sáng tỏ chính sự mà không vội phán đoán.",giai:"Hình thức và vẻ ngoài được chú trọng, giao tiếp hài hòa đem lại thiện cảm. Tuy nhiên nên giữ sự chân thật bên trong, chớ để vẻ hào nhoáng lấn át thực chất.",lines:["Sơ Cửu: Làm đẹp đôi chân bằng việc đi bộ, từ chối xe sang giữ trọn thanh danh.","Lục Nhị: Chăm chút râu ria theo dáng vẻ người, nương tựa người trên để tròn bổn phận.","Cửu Tam: Tươi tắn rạng rỡ đượm vẻ sắc son, giữ lòng bền chặt đón nhận điềm may.","Lục Tứ: Trắng trẻo mộc mạc như ngựa có cánh, cầu bạn kết duyên chẳng chút ngờ nghi.","Lục Ngũ: Trang hoàng vườn tược lụa là đơn sơ, tuy ít lễ vật nhưng lòng chân thành.","Thượng Cửu: Giữ nét mộc mạc giản dị ban đầu, chẳng cần điểm tô mà việc vẫn tròn."]},{num:23,name:"Bác",upper:"Cấn",lower:"Khôn",verdict:"hung",guaci:"Đất đá lở rụng thế suy tàn, chẳng lợi đi đâu hãy giữ yên mình.",tuong:"Núi gắn trên đất lâu ngày lở sạt, người trên thương xót người dưới để yên ngôi vị.",giai:"Thời vận sa sút, nền tảng lung lay và dễ gặp tiểu nhân quấy phá. Chớ nên khởi sự lớn hay đối đầu trực diện, hãy lui về củng cố nội lực và bảo toàn bản thân.",lines:["Sơ Lục: Chân giường bị mục rỗng từ bên dưới, nền móng lung lay chuốc lấy điều hung.","Lục Nhị: Rường giường nứt gãy lún sâu dần đều, hiểm nguy cận kề chẳng nên coi thường.","Lục Tam: Lạc lõng rụng rơi giữa chốn rối ren, lìa xa phường xấu không mắc sai lầm.","Lục Tứ: Hư hỏng lan lên tận chiếu nằm rồi, tai họa sát người vô cùng nguy ngập.","Lục Ngũ: Cung nữ dắt tay như đàn cá bơi, nhờ ơn sủng ái việc chẳng có lo.","Thượng Cửu: Trái to sót lại chưa rụng khỏi cành, quân tử được xe tiểu nhân tan nhà."]},{num:24,name:"Phục",upper:"Khôn",lower:"Chấn",verdict:"cat",guaci:"Đạo lành quay lại vạn sự hanh thông, ra vào không hại ngày xuân hồi sinh.",tuong:"Sấm vang âm ỉ trong lòng đất sâu, ngày đông đóng cửa nghỉ ngơi chờ thời.",giai:"Thời kỳ bế tắc đã qua, sinh khí và cơ hội mới bắt đầu nhen nhóm quay lại. Hãy bắt đầu từng bước vững chắc, sửa đổi sai lầm cũ và đón nhận tương lai tươi sáng.",lines:["Sơ Cửu: Đi lạc không xa vội quay đầu lại, không chút hối tiếc gặp điềm đại cát.","Lục Nhị: Vui vẻ quay về noi gương người hiền, giữ lòng hướng thiện đón nhận điềm may.","Lục Tam: Tần ngần tráo trở quay lại nhiều lần, có chút hiểm nguy nhưng không vạ lớn.","Lục Tứ: Cùng bước giữa dòng biết tách quay về, đi theo đường chính chẳng sợ lạc lối.","Lục Ngũ: Thành tâm hối lỗi tự giác quay về, dốc lòng hướng thiện không điều hối tiếc.","Thượng Lục: Lạc lối mê muội chẳng chịu quay đầu, đem quân chinh phạt chuốc lấy bại vong."]},{num:25,name:"Vô Vọng",upper:"Càn",lower:"Chấn",verdict:"cat",guaci:"Giữ lòng chân thật chớ có cuồng vọng, thuận theo đạo trời ắt được hanh thông.",tuong:"Dưới trời sấm động chuyển biến muôn loài, người xưa theo thời chăm lo gieo cấy.",giai:"Nên sống chân thành, làm việc ngay thẳng và không mưu toan vụ lợi. Tránh hành động liều lĩnh mù quáng, cứ thuận theo tự nhiên thì mọi sự đều xuôi chèo mát mái.",lines:["Sơ Cửu: Giữ tâm chân chất không chút dối gian, tiến bước làm việc gặp điều tốt lành.","Lục Nhị: Chẳng mong gặt lúa khi chưa cày sâu, chuyên tâm lao động tự khắc có quả.","Lục Tam: Tai bay vạ gió bất ngờ ập tới, trâu người đi lạc dân làng chịu oan.","Cửu Tứ: Giữ vững chính đạo an phận thủ thường, không màng danh ảo tai qua nạn khỏi.","Cửu Ngũ: Bệnh tật ập đến không do lỗi mình, chớ uống thuốc bậy bệnh tự tiêu tan.","Thượng Cửu: Cứ gượng tiến bước khi hết duyên lành, manh động vọng tưởng chuốc lấy tai ương."]},{num:26,name:"Đại Súc",upper:"Cấn",lower:"Càn",verdict:"cat",guaci:"Tích lũy tài đức vượt qua sông sâu, không ăn cơm nhà ra đời lập nghiệp.",tuong:"Trong lòng núi cao chứa cả trời rộng, quân tử ghi nhớ điều xưa bồi đắp đức dày.",giai:"Thời vận tích tụ nội lực dồi dào, tri thức và kinh nghiệm chín muồi. Thích hợp đảm đương việc lớn, học hỏi trau dồi và chuẩn bị vươn xa.",lines:["Sơ Cửu: Thấy trước hiểm nguy tạm dừng bước chân, biết giữ an toàn không lo mắc lỗi.","Cửu Nhị: Tháo trục rời xe chẳng dám đi xa, bình tâm chờ đợi thời cơ thuận hòa.","Cửu Tam: Ngựa tốt phi nhanh rèn luyện mỗi ngày, giữ lòng phòng bị tiến bước bình an.","Lục Tứ: Đóng ván chắn trán bò con từ nhỏ, ngừa trước tai họa điềm lành nở hoa.","Lục Ngũ: Bẻ nanh lợn rừng thuần hóa dữ tợn, việc làm khôn khéo gặp nhiều điềm may.","Thượng Cửu: Đường trời rộng mở thênh thang bốn bề, thỏa sức vẫy vùng hanh thông muôn lối."]},{num:27,name:"Di",upper:"Cấn",lower:"Chấn",verdict:"trung",guaci:"Tự nuôi thân mình xem xét lời ăn, giữ gìn tiết độ việc ắt tốt tươi.",tuong:"Dưới núi có sấm chấn động gầm vang, quân tử cẩn trọng lời nói dè dặt ăn uống.",giai:"Nhắc nhở chú trọng việc nuôi dưỡng thân tâm, cẩn trọng lời ăn tiếng nói và cách chi tiêu. Chớ tham lam hưởng thụ hay can thiệp việc người khác ngoài phận sự.",lines:["Sơ Cửu: Bỏ rùa thiêng quý thèm muốn việc người, tham lam ngó nghiêng chuốc lấy chê cười.","Lục Nhị: Cầu ăn trái lẽ ngửa tay xin xỏ, bỏ chỗ bằng phẳng gặp bước gian nan.","Lục Tam: Trái ngược đạo nuôi mải mê hưởng lạc, mười năm lầm lỡ chẳng làm nên chi.","Lục Tứ: Tìm nguồn nuôi dưỡng chia sẻ cùng người, mắt hổ rình mồi không lo lầm lỗi.","Lục Ngũ: Trái lẽ thường tình nên ở yên chỗ, qua sông lớn hiểm chớ vội bước chân.","Thượng Cửu: Gánh vác việc nuôi dưỡng cả thiên hạ, dẫu gặp hiểm nguy cuối cùng thành công."]},{num:28,name:"Đại Quá",upper:"Đoài",lower:"Tốn",verdict:"hung",guaci:"Kèo cột cong oằn gánh nặng quá sức, khéo léo tiến lui mới mong bình an.",tuong:"Đầm nước dâng cao ngập cả cây rừng, người quân tử đứng riêng chẳng sợ vui một mình.",giai:"Tình thế quá tải, gánh vác áp lực vượt quá sức chịu đựng thông thường. Cần giảm bớt gánh nặng, linh hoạt xử lý và tìm thêm trợ lực trước khi đổ vỡ.",lines:["Sơ Lục: Lót cỏ trắng mềm đặt đồ quý giá, cẩn thận từ đầu không mắc sai lầm.","Cửu Nhị: Cây dương già cỗi nảy mầm chồi non, lão ông cưới vợ không gì chẳng vui.","Cửu Tam: Cột nhà cong gãy vì chở quá nặng, nguy hiểm cận kề chẳng biết cậy ai.","Cửu Tứ: Cột nhà dựng thẳng vững vàng chống đỡ, nếu có lòng riêng ắt gặp thẹn thùng.","Cửu Ngũ: Cây liễu khô cằn trổ hoa muộn màng, lão bà lấy chồng chẳng khen chẳng chê.","Thượng Lục: Lội qua dòng nước ngập lút cả đầu, dẫu gặp hoạn nạn nhưng lòng không sai."]},{num:29,name:"Khảm",upper:"Khảm",lower:"Khảm",verdict:"hung",guaci:"Hiểm nguy trùng điệp giữ vững niềm tin, trong lòng hanh thông vượt qua vực sâu.",tuong:"Nước chảy cuồn cuộn không ngừng ngày đêm, quân tử giữ nếp đức hạnh rèn luyện bản thân.",giai:"Đang ở giữa cảnh hiểm trở, khó khăn liên tiếp ập đến thử thách bản lĩnh. Cần bình tĩnh, giữ tâm trong sáng ngay thẳng và bước từng bước thận trọng để vượt nạn.",lines:["Sơ Lục: Hố sâu trùng điệp trượt ngã vào trong, quen thói làm càn rước lấy tai ương.","Cửu Nhị: Giữa nơi hãm hiểm có chút nguy nan, chỉ cầu việc nhỏ chớ mong việc to.","Lục Tam: Tới lui đều vướng hố sâu thăm thẳm, chớ nên manh động hãy đứng yên chân.","Lục Tứ: Một bầu rượu nhạt chén đất thô sơ, cửa sổ đưa tin cuối cùng bình an.","Cửu Ngũ: Nước đọng vừa đầy không tràn bờ bến, phẳng lặng êm đềm tai họa dần tan.","Thượng Lục: Dây trói ba tầng giam nơi ngục tối, ba năm quạnh quẽ chịu cảnh lầm than."]},{num:30,name:"Ly",upper:"Ly",lower:"Ly",verdict:"cat",guaci:"Lửa sáng bập bùng nương tựa việc chính, nuôi bò cái hiền gặp điều cát tường.",tuong:"Ánh sáng nối tiếp rực rỡ trời cao, người lớn kế thừa đức sáng soi khắp muôn phương.",giai:"Thời vận rạng rỡ, trí tuệ minh mẫn và các mối quan hệ nương tựa lẫn nhau tốt đẹp. Cần dựa vào người có đức độ, giữ sự nhu thuận và chớ kiêu căng nóng vội.",lines:["Sơ Cửu: Bước chân vội vã lúc sớm ban mai, kính cẩn thận trọng tránh khỏi lỗi lầm.","Lục Nhị: Sắc vàng rực rỡ tỏa sáng giữa trưa, giữ đạo trung hòa gặp điềm đại cát.","Cửu Tam: Bóng chiều ngả xế than khóc tuổi già, không gõ hũ hát ắt sinh muộn phiền.","Cửu Tứ: Bùng cháy đột ngột đốt hết mọi điều, chết chóc bỏ rơi tai họa ập đến.","Lục Ngũ: Lệ tuôn ròng rã tiếng thở dài than, biết sợ giữ mình cuối cùng gặp may.","Thượng Cửu: Ra quân dẹp loạn bắt kẻ đầu sỏ, tha kẻ a dua tiếng thơm vang rền."]},{num:31,name:"Hàm",upper:"Đoài",lower:"Cấn",verdict:"cat",guaci:"Cảm ứng hòa hợp lòng người gắn kết, lấy vợ hiền thục vạn sự hanh thông.",tuong:"Trên núi có đầm nước mát trong veo, người quân tử rỗng lòng đón nhận người khác.",giai:"Tình cảm nảy nở, đôi bên thấu hiểu và hòa hợp tự nhiên trong công việc cũng như tình duyên. Hãy mở rộng lòng mình, chân thành đối đãi để đón nhận tình thân ái.",lines:["Sơ Lục: Rung động ngón chân mới chớm ý định, giữ lòng trong sáng chẳng có lỗi chi.","Lục Nhị: Rung động bắp chuối dùng dằng muốn đi, ở yên chờ đợi tránh nỗi muộn phiền.","Cửu Tam: Rung động nơi đùi chạy theo chân người, câu nệ nông nổi chuốc lấy hổ ngươi.","Cửu Tứ: Giữ lòng chính trực điềm lành gõ cửa, lui tới băn khoăn bạn bè ngóng trông.","Cửu Ngũ: Rung động nơi lưng không màng dao động, giữ tâm thanh tịnh chẳng chút ăn năn.","Thượng Lục: Rung động môi mép chỉ khéo ba hoa, lời hay ý đẹp chưa chắc chân thành."]},{num:32,name:"Hằng",upper:"Chấn",lower:"Tốn",verdict:"cat",guaci:"Bền bỉ kiên định việc ắt thành công, trước sau như một không lo lỡ bước.",tuong:"Sấm gió cùng nhau tương trợ chuyển dời, quân tử đứng thẳng không đổi hướng đi.",giai:"Tượng trưng cho sự bền bỉ, thủy chung và kiên định với mục tiêu đã chọn. Giữ vững nề nếp kỷ cương, làm việc có kế hoạch lâu dài sẽ đạt được thành tựu vững chắc.",lines:["Sơ Lục: Cầu bền quá vội đốt cháy giai đoạn, nôn nóng muốn thành chuốc lấy điều hung.","Cửu Nhị: Hối tiếc tiêu tan giữ đạo trung dung, bền lòng nhẫn nại đường xa ngại gì.","Cửu Tam: Đổi dạ thay lòng không giữ được bền, chuốc lấy hổ thẹn xấu xa với người.","Cửu Tứ: Giăng lưới bãi cạn làm sao bắt cá, sai chỗ sai đường uổng phí công lao.","Lục Ngũ: Bền bỉ giữ nết theo sau phụ mẫu, đàn bà thì tốt đàn ông lụy mình.","Thượng Lục: Đứng ngồi không yên tráo trở đổi dời, lòng dạ xao động chuốc lấy gian truân."]},{num:33,name:"Độn",upper:"Càn",lower:"Cấn",verdict:"trung",guaci:"Biết lui biết giữ để tránh rủi ro, khôn ngoan nhường bước bảo toàn thân mình.",tuong:"Dưới trời có núi sừng sững xa xăm, người hiểu sự đời lánh xa kẻ tiểu nhân mà giữ lấy uy nghiêm.",giai:"Thời thế chưa thuận nên tạm thời lui bước, không nên cưỡng cầu tiến tới kẻo vướng điều bất lợi. Giữ mình kín kẽ, tích lũy nội lực đợi ngày vận hội hanh thông.",lines:["Sơ Lục: Độn ở phía sau chưa kịp dời chân, manh động lúc này dễ gặp điều bất lợi.","Lục Nhị: Dùng da bò vàng buộc chặt giữ mình, một lòng kiên định không ai lay chuyển.","Cửu Tam: Vướng víu dây dưa lùi bước nặng nề, cưu mang bề dưới tránh đường hiểm nguy.","Cửu Tứ: Tự giác lui bước giữ trọn phong thái, người hiểu thời thế chẳng tiếc việc lui.","Cửu Ngũ: Rút lui đúng lúc lòng dạ thanh thản, giữ tâm ngay thẳng việc ắt bình yên.","Thượng Cửu: Lánh xa trần tục nhẹ gánh âu lo, thong dong tự tại chẳng chút vấn vương."]},{num:34,name:"Đại Tráng",upper:"Chấn",lower:"Càn",verdict:"cat",guaci:"Khí thế đang lên mạnh mẽ vững vàng, giữ đức chính đính thì việc lớn hanh thông.",tuong:"Sấm vang chớp giật trên trời lồng lộng, người giữ khuôn phép không đi sai đường lạc lối.",giai:"Vận khí đang độ sung mãn, sức lực dồi dào để làm nên việc lớn. Tuy nhiên chớ cậy mạnh mà hành động nông nổi, cần lấy sự chừng mực và khéo léo làm gốc.",lines:["Sơ Cửu: Cậy mạnh nơi ngón chân vội vã tiến bước, nôn nóng đi đầu chuốc lấy thất bại.","Cửu Nhị: Giữ đức trung hòa không khoe sức mạnh, kiên định vững vàng ắt gặp điều lành.","Cửu Tam: Kẻ dại dùng sức húc giậu mắc sừng, bốc đồng hung hăng tự làm khổ mình.","Cửu Tứ: Rào dậu mở toang xe lăn êm ả, dốc sức đúng lúc trở ngại tiêu tan.","Lục Ngũ: Mất dê ngoài đồng chẳng chút bận lòng, buông bỏ nhẹ nhàng không vướng ân hận.","Thượng Lục: Húc giậu mắc sừng tiến thoái lưỡng nan, biết khó chịu dừng mới mong ổn thỏa."]},{num:35,name:"Tấn",upper:"Ly",lower:"Khôn",verdict:"cat",guaci:"Mặt trời mọc sáng rọi chiếu muôn nơi, lòng người hướng thiện vạn sự vươn lên.",tuong:"Ánh sáng mặt trời vươn lên trên mặt đất, người quân tử rạng danh bằng đức hạnh sáng ngời.",giai:"Thời vận đang lên như mặt trời ban mai, được cấp trên tín nhiệm và mọi người ủng hộ. Cần giữ lòng trung thực, khiêm tốn học hỏi để bước tiến thêm vững chắc dài lâu.",lines:["Sơ Lục: Muốn tiến bị ngăn giữ lòng khoan dung, rộng mở tâm hồn không lo trách cứ.","Lục Nhị: Bước tiến ngập ngừng mang nỗi sầu lo, giữ lòng ngay thẳng được bề trên chở che.","Lục Tam: Lòng người đồng thuận muôn nẻo tin theo, hối tiếc tiêu tan mưu sự dần thành.","Cửu Tứ: Tiến nhanh như chuột tham lam giấu đồ, giữ lòng ngay thẳng đề phòng hiểm nguy.","Lục Ngũ: Mất mát chẳng lo được thua chẳng quản, vững bước tiến lên đón nhận niềm vui.","Thượng Cửu: Tiến đến tận cùng chỉ nên sửa mình, phòng ngừa sơ suất chớ phạt người ngoài."]},{num:36,name:"Minh Di",upper:"Khôn",lower:"Ly",verdict:"hung",guaci:"Ánh sáng bị vùi lấp dưới lòng đất, giấu tài ẩn nhẫn giữ dạ sắt son.",tuong:"Ánh sáng chìm sâu vào lòng đất tăm tối, người khôn ngoan biết giấu mình để vượt qua nguy nan.",giai:"Đang ở vào hoàn cảnh trắc trở, dễ bị hiểu lầm hoặc dèm pha chèn ép. Tốt nhất nên giấu kín tài năng, nhẫn nại chờ thời và giữ gìn đạo đức trong sạch.",lines:["Sơ Cửu: Ánh sáng bị che chim sà gãy cánh, nhịn đói dời chân người ngoài gièm pha.","Lục Nhị: Bị thương đùi trái mượn sức ngựa bền, vượt qua hoạn nạn giữ trọn bình an.","Cửu Tam: Đi săn phương nam gặp kẻ cầm đầu, chớ nên vội vã cần sửa từ từ.","Lục Tứ: Thấu rõ hiểm nguy nơi hang ổ tối, rời xa bóng đêm tìm lối thoát thân.","Lục Ngũ: Giấu kín ánh sáng giữ trọn lòng son, khéo léo nhẫn nhịn qua ngày gian nan.","Thượng Lục: Trước bay lên trời sau chìm xuống đất, kiêu căng hống hách chuốc lấy tối tăm."]},{num:37,name:"Gia Nhân",upper:"Tốn",lower:"Ly",verdict:"cat",guaci:"Đạo nhà êm ấm trên kính dưới nhường, người trong một nhà hòa thuận thì việc ngoài mới nên.",tuong:"Gió thổi bùng lên ngọn lửa ấm nồng, người nói lời chân thật và làm việc kiên định.",giai:"Gia đạo bình an, các thành viên đồng lòng hỗ trợ lẫn nhau. Muốn sự nghiệp vững vàng trước hết phải thu xếp việc nhà chu đáo, dĩ hòa vi quý và giữ đúng đạo lý.",lines:["Sơ Cửu: Giữ nghiêm gia phong ngay từ lúc đầu, kỷ cương chặt chẽ tránh nỗi ăn năn.","Lục Nhị: Chu toàn việc bếp chăm sóc trong nhà, dịu dàng nhu thuận hưởng trọn ấm êm.","Cửu Tam: Trong nhà răn dạy nghiêm khắc đôi khi, còn hơn cười cợt buông lỏng gia phong.","Lục Tứ: Gia đình sung túc nền nếp thuận hòa, trên dưới một lòng phúc lộc tràn đầy.","Cửu Ngũ: Người chủ mẫu mực yêu thương chan hòa, gia đình kính phục chẳng chút âu lo.","Thượng Cửu: Uy nghiêm mẫu mực sau trước vẹn toàn, giữ trọn nề nếp tiếng thơm lưu truyền."]},{num:38,name:"Khuê",upper:"Ly",lower:"Đoài",verdict:"hung",guaci:"Bất đồng chia rẽ trái ngược ý nhau, việc nhỏ làm được việc lớn chớ vội.",tuong:"Lửa bốc lên cao đầm nước chảy xuống, người quân tử tìm điểm tương đồng giữa muôn điều khác biệt.",giai:"Thời điểm dễ nảy sinh bất đồng, mâu thuẫn quan điểm hoặc hiểu lầm nội bộ. Cần giữ bình tĩnh, tôn trọng sự khác biệt và tìm kiếm tiếng nói chung thay vì đối đầu gay gắt.",lines:["Sơ Cửu: Ngựa chạy mất đi chẳng cần tìm kiếm, tự khắc quay về tránh được lỗi lầm.","Cửu Nhị: Gặp người tri kỷ nơi hẻm quanh co, tình cờ tương ngộ chẳng mắc sai lầm.","Lục Tam: Xe bị kéo giật bò bị giữ chân, chịu nhiều oan ức sau lại tốt lành.","Cửu Tứ: Lẻ loi cách biệt gặp bạn tâm giao, đồng lòng gắn bó không sợ hiểm nguy.","Lục Ngũ: Người thân cắn thịt cùng sẻ chia lòng, dốc bầu tâm sự lo gì trở ngăn.","Thượng Cửu: Nhìn nhầm thành lợn ngỡ quỷ đầy xe, buông cung cởi giáp nhận lại người thương."]},{num:39,name:"Kiển",upper:"Khảm",lower:"Cấn",verdict:"hung",guaci:"Núi cao hiểm trở đường sá gập ghềnh, dừng bước suy xét tìm lối đi thông.",tuong:"Trên núi có dòng nước sâu hiểm hóc, người quân tử tự nhìn lại mình để rèn luyện đức độ.",giai:"Gặp nhiều trở ngại và thử thách ngáng đường, chưa thể tiến nhanh hay mở rộng quy mô. Hãy bình tâm xem xét lại bản thân, tìm sự trợ giúp của bạn bè đồng sự và đợi thời cơ.",lines:["Sơ Lục: Tiến tới gặp khó quay về nghỉ ngơi, biết dừng đúng lúc giữ được an toàn.","Lục Nhị: Bề tôi nhọc nhằn gánh vác việc chung, vì việc nghĩa hiệp chẳng vì lợi riêng.","Cửu Tam: Tiến bước trắc trở quay lại ấm êm, trở về gia quyến đón nhận niềm vui.","Lục Tứ: Tiến bước gặp khó liền kết bạn hiền, cùng chung gánh vác đỡ nỗi nhọc nhằn.","Cửu Ngũ: Gian truân chất chồng bạn hữu đến cứu, đồng cam cộng khổ vượt ải khó khăn.","Thượng Lục: Tiến tới gian truân quay lại gặp may, tìm người đức cao cùng lo việc đời."]},{num:40,name:"Giải",upper:"Chấn",lower:"Khảm",verdict:"cat",guaci:"Mưa tan sấm dứt mây mù tiêu tan, cởi bỏ trói buộc lòng nhẹ thảnh thơi.",tuong:"Sấm động kèm mưa trút xuống đất lành, người tha thứ lỗi lầm rộng lượng bao dung.",giai:"Mọi khúc mắc, hiểu lầm và khó khăn đang dần được tháo gỡ như mưa rào tan mây. Nên tha thứ cho những va chạm cũ, giải quyết dứt điểm các vướng mắc còn tồn đọng.",lines:["Sơ Lục: Nguy nan vừa dứt lòng dạ thảnh thơi, không còn lỗi lầm mọi việc dần yên.","Cửu Nhị: Bắn được ba cáo nơi chốn đồng hoang, được mũi tên vàng giữ trọn lòng ngay.","Lục Tam: Gánh nặng trên vai lại ngồi xe ngựa, khoe khoang kệch cỡm chuốc lấy trộm cướp.","Cửu Tứ: Tháo bỏ dây trói ngón chân vướng víu, bạn bè tin tưởng cùng đến giúp tay.","Lục Ngũ: Kẻ tốt cởi bỏ trói buộc tiểu nhân, giải tỏa muộn phiền giữ điều cát tường.","Thượng Lục: Bắn trúng chim ưng trên tường thành cao, dứt khoát ra tay trừ ngay mầm họa."]},{num:41,name:"Tổn",upper:"Cấn",lower:"Đoài",verdict:"trung",guaci:"Bớt dưới thêm trên giữ lòng thành tín, biết hy sinh nhỏ sẽ đón việc lành.",tuong:"Dưới núi có đầm sâu nuôi dưỡng vạn vật, người biết kiềm chế nóng giận và ngăn bớt dục vọng.",giai:"Tượng trưng cho sự hy sinh, bớt phần riêng để lo việc chung, chịu thiệt thòi trước mắt để hưởng lợi bền lâu. Cần giữ lòng chân thành, kiềm chế tính khí và chi tiêu hợp lý.",lines:["Sơ Cửu: Xong việc vội vã đến giúp người ngay, chớ nên quá mức biết giữ chừng mực.","Cửu Nhị: Giữ lòng chính trực có lợi dài lâu, không làm tổn mình mà ích cho người.","Lục Tam: Ba người cùng đi bớt đi một người, một người đơn độc ắt gặp bạn thân.","Lục Tứ: Giảm bớt tật xấu sửa chữa lỗi lầm, nhanh nhẹn đổi thay đón niềm hoan hỷ.","Lục Ngũ: Có người đem rùa quý giá đến dâng, chẳng thể chối từ phúc lành tự tới.","Thượng Cửu: Giúp người trọn vẹn chẳng tổn hại mình, khắp chốn chung tay được lòng thiên hạ."]},{num:42,name:"Ích",upper:"Tốn",lower:"Chấn",verdict:"cat",guaci:"Gió đưa sấm rền muôn vật thêm tươi, giúp người cứu khó ắt được phúc dày.",tuong:"Gió cùng sấm sét trợ lực lẫn nhau, người thấy điều thiện thì làm thấy lỗi thì sửa.",giai:"Vận may đang tới, có cơ hội gia tăng thêm tài lực, tri thức và mở rộng quan hệ. Nên đem khả năng giúp đỡ người khác, chia sẻ lợi ích thì thành quả mới bền chặt.",lines:["Sơ Cửu: Làm nên việc lớn thời điểm thuận hòa, dốc lòng thực hiện gặp điềm đại cát.","Lục Nhị: Được người giúp sức ban tặng rùa quý, giữ lòng bền chặt việc ắt hanh thông.","Lục Tam: Lấy điều trắc trở làm sự rèn lòng, giữ dạ sắt son bước đi vững chãi.","Lục Tứ: Đứng giữa hòa giải chuyển dời kinh đô, làm việc công tâm được người tín nhiệm.","Cửu Ngũ: Lấy đức ban ơn thương dân hết lòng, chẳng cần gặng hỏi cũng được phúc lành.","Thượng Cửu: Chẳng giúp cho ai lại cầu lợi riêng, lòng dạ tham lam chuốc điều rủi ro."]},{num:43,name:"Quải",upper:"Đoài",lower:"Càn",verdict:"trung",guaci:"Quyết đoán trừ tà giãi bày việc ngay, dùng đức cảm hóa chớ chuộng vũ lực.",tuong:"Đầm dâng lên trời nguy cơ vỡ bờ, người rộng lòng ban ơn chớ cậy giàu sang.",giai:"Thời điểm cần đưa ra quyết định dứt khoát, loại bỏ thói quen xấu hoặc mối quan hệ tiêu cực. Tuy nhiên cần hành động minh bạch, khéo léo và không nên dùng biện pháp quá cực đoan.",lines:["Sơ Cửu: Ngón chân tiến mạnh không cân sức mình, vội vã xông pha chuốc lấy thất bại.","Cửu Nhị: Cảnh giác đêm hôm tiếng kêu lo sợ, giữ sẵn phòng bị không lo hiểm nguy.","Cửu Tam: Mặt nổi giận dữ một mình dầm mưa, gặp điều trắc trở nhưng không lỗi gì.","Cửu Tứ: Mông đau tróc da bước đi ngập ngừng, dắt dê theo lối chớ nói lời thừa.","Cửu Ngũ: Nhổ sạch cỏ lác giữ đạo trung dung, quyết đoán hành động tránh điều ân hận.","Thượng Lục: Tiếng khóc nghẹn ngào chẳng người cứu giúp, cố chấp bướng bỉnh cuối cùng gặp hung."]},{num:44,name:"Cấu",upper:"Càn",lower:"Tốn",verdict:"hung",guaci:"Gặp gỡ bất ngờ duyên phận tao ngộ, chớ thấy dịu dàng mà vội nhẹ dạ.",tuong:"Dưới trời gió thổi lan tỏa bốn phương, người ban hành mệnh lệnh truyền khắp muôn dân.",giai:"Báo hiệu sự gặp gỡ tình cờ, duyên may tao ngộ hoặc có yếu tố mới xuất hiện. Cần tỉnh táo quan sát, giữ nguyên tắc đạo đức và tránh nhẹ dạ cả tin trước lời ngon ngọt.",lines:["Sơ Lục: Buộc vào hãm xe bằng phanh đồng bền, giữ mình dừng bước phòng ngừa hiểm nguy.","Cửu Nhị: Trong bếp có cá giữ kín phần mình, chớ để khách ngoài nhòm ngó dòm nom.","Cửu Tam: Đùi đau tróc da bước đi khập khiễng, nguy khôn lường nhưng không mắc lỗi lầm.","Cửu Tứ: Trong bếp không cá mất đi bạn hiền, xa cách lòng người chuốc lấy rủi ro.","Cửu Ngũ: Quả dưa bọc lá che chở tài ba, lặng lẽ nuôi dưỡng phúc từ trời ban.","Thượng Cửu: Húc sừng kiêu hãnh không chịu nhún nhường, người ngoài xa lánh chuốc nỗi muộn phiền."]},{num:45,name:"Tụy",upper:"Đoài",lower:"Khôn",verdict:"cat",guaci:"Tụ họp đông vui lòng người hướng về, sửa lễ cúng tế giữ trọn niềm tin.",tuong:"Nước đầm dâng tràn tụ trên mặt đất, người sửa sang khí giới đề phòng biến cố.",giai:"Thời kỳ tụ họp bạn bè, đồng tâm hiệp lực và gắn kết cộng đồng. Cần có người đứng ra dẫn dắt công tâm, duy trì trật tự và phòng ngừa bất trắc khi đám đông tụ họp.",lines:["Sơ Lục: Lòng thành chưa trọn khi loạn khi an, nắm tay nhau cười xua tan âu lo.","Lục Nhị: Chân thành kết nối cảm ứng tự nhiên, lòng thành cúng tế chẳng cần lễ to.","Lục Tam: Muốn nhóm họp lại thở than một mình, đi tới kết giao không mắc lỗi chi.","Cửu Tứ: Gặp vận đại cát nhóm họp bạn hiền, không màng tư lợi chẳng chút lỗi lầm.","Cửu Ngũ: Đứng đầu quy tụ muôn người tin theo, giữ lòng chí công không sinh hối tiếc.","Thượng Lục: Lệ tuôn lã chã thở ngắn than dài, lẻ loi không bạn lòng đầy cô đơn."]},{num:46,name:"Thăng",upper:"Khôn",lower:"Tốn",verdict:"cat",guaci:"Từng bước vươn lên như cây mọc thẳng, tìm người đức độ để gửi niềm tin.",tuong:"Cây non trong lòng đất lớn dần vươn cao, người tích lũy điều thiện từ việc nhỏ nên lớn.",giai:"Vận thế đang dần đi lên một cách vững chắc, ví như mầm cây đâm chồi vươn cao đón nắng. Hãy kiên trì tích lũy kinh nghiệm, làm tốt từng việc nhỏ và khiêm nhường học hỏi.",lines:["Sơ Lục: Được người nâng đỡ cất bước thăng tiến, lòng dạ thành tâm gặp điều đại cát.","Cửu Nhị: Lòng thành dâng lễ dẫu nhỏ mà vui, giữ lòng chân thật không vướng âu lo.","Cửu Tam: Thẳng bước tiến lên vào chốn thành hoang, không chút nghi ngờ đường quang thênh thang.","Lục Tứ: Bậc trên ban thưởng làm lễ núi Kỳ, thuận hòa cung kính gặp điều cát tường.","Lục Ngũ: Từng bước tiến lên bậc thềm danh vọng, giữ vững đạo tâm mưu sự đều xuôi.","Thượng Lục: Mù quáng tiến mãi trong chốn tối tăm, giữ lòng kiên định mới mong vẹn toàn."]},{num:47,name:"Khốn",upper:"Đoài",lower:"Khảm",verdict:"hung",guaci:"Bế tắc gian truân thử thách lòng dạ, lời nói khó tin chỉ nên giữ chí.",tuong:"Đầm cạn hết nước khô cạn trơ đáy, người quân tử giữ trọn chí khí dẫu lúc gian nan.",giai:"Rơi vào giai đoạn thử thách gắt gao, thiếu thốn nguồn lực và khó tìm người thấu hiểu. Đừng buông xuôi hay nói lời phân bua vô ích, hãy kiên cường chịu đựng rèn luyện bản lĩnh.",lines:["Sơ Lục: Ngồi khốn gốc cây vào hang tối tăm, ba năm quạnh quẽ không thấy bóng người.","Cửu Nhị: Khốn bên rượu thịt áo đỏ tìm về, thành tâm cúng tế tai họa dần qua.","Lục Tam: Vướng vào đá sỏi dựa bụi gai góc, về nhà vắng bóng chuốc nỗi xót xa.","Cửu Tứ: Bước đi chậm chạp vướng cỗ xe vàng, có chút ngập ngừng nhưng rồi cũng xong.","Cửu Ngũ: Bị cắt mũi chân nỗi đau giày vò, giữ lòng trung chính từ từ vượt qua.","Thượng Lục: Vướng vào dây leo bước đi chông chênh, hối hận sửa mình thoát cảnh khốn cùng."]},{num:48,name:"Tỉnh",upper:"Khảm",lower:"Tốn",verdict:"trung",guaci:"Đổi làng không đổi giếng nguồn nước mát trong, nuôi dưỡng không ngừng chớ để vỡ bình.",tuong:"Nước ngầm trong lòng đất nuôi sống cây cối, người lấy đức độ khuyên nhủ giúp đỡ muôn dân.",giai:"Tượng trưng cho nguồn lực nội tại vô tận và sự sẻ chia phục vụ cộng đồng. Cần thường xuyên tu dưỡng phẩm chất, chia sẻ tri thức và cẩn trọng trong từng bước để không làm hỏng công sức.",lines:["Sơ Lục: Đáy giếng bùn lầy nước không uống được, giếng cũ bỏ hoang chim chóc chẳng màng.","Cửu Nhị: Đáy giếng bắn cá vại thủng nước tràn, phí hoài tài năng chẳng giúp ích chi.","Cửu Tam: Giếng sạch trong veo chưa người múc nước, tiếc cho tài giỏi chưa gặp được thời.","Lục Tứ: Xây lát thành giếng tu bổ khang trang, cẩn thận sửa sang không mắc lỗi lầm.","Cửu Ngũ: Giếng nước mát lành suối nguồn ngọt ngào, nuôi dưỡng muôn người phúc đức vô cùng.","Thượng Lục: Giếng khơi không đậy ban phát cho đời, rộng lòng chia sẻ gặp điềm đại cát."]},{num:49,name:"Cách",upper:"Đoài",lower:"Ly",verdict:"cat",guaci:"Đổi cũ thay mới hợp lòng người, giữ đức chí thành ắt việc hanh thông.",tuong:"Đầm nước có lửa bốc cháy bừng bừng, người xem xét thời thế mà sửa đổi lịch trình.",giai:"Thời kỳ chuyển mình bỏ cũ đón mới, cần quyết đoán loại bỏ thói quen lạc hậu. Hành động đúng thời điểm và nhận được sự đồng thuận sẽ gặt hái kết quả tốt lành.",lines:["Sơ Cửu: Buộc chắc bằng da bò vàng, giữ mình cẩn trọng chớ vội đổi thay.","Lục Nhị: Đến ngày mới tiến hành cải cách, thuận theo thời thế ắt gặp điềm lành.","Cửu Tam: Bàn thảo ba phen tính kế chu toàn, thuận lòng muôn người mới nên xuất hành.","Cửu Tứ: Lòng tin trọn vẹn thay đổi số mệnh, gạt bỏ lo âu hướng tới điều hay.","Cửu Ngũ: Bậc tài đức biến hóa tựa hổ lớn, chưa cần bói toán lòng người đã theo.","Thượng Lục: Người khéo sửa mình đổi mới diện mạo, giữ lòng yên phận để được bền lâu."]},{num:50,name:"Đỉnh",upper:"Ly",lower:"Tốn",verdict:"cat",guaci:"Lửa đượm đun sôi nuôi dưỡng hiền tài, giữ lòng vững chãi gặp điều đại cát.",tuong:"Gió thổi nuôi ngọn lửa bùng cháy, người quân tử chính trực làm tròn sứ mệnh.",giai:"Thời vận vững vàng và phát triển hưng thịnh, tượng trưng cho sự ổn định và dưỡng dục nhân tài. Nên phát huy đức độ, xây dựng nền tảng vững chắc và gắn kết những người có chí hướng.",lines:["Sơ Lục: Chổng ngược chân vạc trút hết cặn nhơ, đón điều mới mẻ không mắc lỗi lầm.","Cửu Nhị: Trong vạc đầy ắp đồ ăn tươi ngon, cẩn trọng giữ mình tránh kẻ ghen ghét.","Cửu Tam: Tai vạc trật khớp khó nhấc nồi cơm, chờ mưa thuận gió hòa mới hết ưu phiền.","Cửu Tứ: Chân vạc gãy gập làm đổ thức ăn, gánh vác quá sức chuốc lấy hổ thẹn.","Lục Ngũ: Tai vạc bằng vàng quai tròn khảm ngọc, giữ lòng trung chính ắt hưởng an vui.","Thượng Cửu: Quai ngọc sáng ngời ngự trên đỉnh đồng, phúc đức vẹn toàn muôn sự hanh thông."]},{num:51,name:"Chấn",upper:"Chấn",lower:"Chấn",verdict:"trung",guaci:"Sấm vang trăm dặm giật mình kinh sợ, lòng dạ vững vàng nụ cười rạng rỡ.",tuong:"Sấm sét liên hoàn kinh động đất trời, người biết sợ uy trời mà tự sửa mình tu đức.",giai:"Thời điểm có nhiều biến động bất ngờ gây hoang mang lo lắng. Nếu bình tâm đối diện, giữ vững tinh thần và không hoảng loạn thì tai qua nạn khỏi, an ổn lâu dài.",lines:["Sơ Cửu: Tiếng sấm rền vang kinh hãi ban đầu, sau cười ha hả lòng nhẹ thảnh thơi.","Lục Nhị: Sấm động nguy nan leo lên gò cao, của mất chớ tìm bảy ngày lại về.","Lục Tam: Tiếng sét giật mình lòng dạ bất an, biết sợ sửa bước không vướng tai ương.","Cửu Tứ: Sấm sét chìm sâu sa vào bùn lầy, thiếu chí quyết đoán khó bề bứt phá.","Lục Ngũ: Sấm động dồn dập qua lại hiểm nguy, bình tĩnh lo liệu không hỏng việc chung.","Thượng Lục: Sấm rung tứ phía ngó nghiêng sợ sệt, lui bước thận trọng tránh được vạ lây."]},{num:52,name:"Cấn",upper:"Cấn",lower:"Cấn",verdict:"trung",guaci:"Dừng lại đúng lúc giữ tâm thanh tịnh, thấy người qua sân chẳng chút bận lòng.",tuong:"Núi lồng bóng núi đứng yên vững chãi, người không để tâm suy nghĩ vượt ngoài bổn phận.",giai:"Thời kỳ nên an tĩnh ngơi nghỉ, không nên nóng vội bon chen hay khởi sự việc mới. Biết dừng lại đúng thời điểm để tĩnh dưỡng tinh thần và nhìn nhận lại bản thân.",lines:["Sơ Lục: Dừng nơi ngón chân chưa bước đi xa, giữ lòng ngay ngắn không chuốc lỗi lầm.","Lục Nhị: Dừng nơi bắp chân chẳng thể kéo người, lòng mang buồn bã khó nỗi sẻ chia.","Cửu Tam: Gượng ép dừng lưng làm đứt sống hông, nóng vội dằn lòng sinh nỗi hiểm nguy.","Lục Tứ: Giữ thân yên ổn dừng ở bờ vai, biết mình biết người không vướng tai họa.","Lục Ngũ: Dừng nơi bờ môi lời ăn tiếng nói, nói năng chừng mực muộn phiền tiêu tan.","Thượng Cửu: Trọn vẹn dừng tâm giữ đạo thuần hậu, kết thúc êm ấm gặp điềm cát tường."]},{num:53,name:"Tiệm",upper:"Tốn",lower:"Cấn",verdict:"cat",guaci:"Tiến bước từ từ như nhạn về bờ, việc cưới việc gả thong thả ắt thành.",tuong:"Cây trên sườn núi lớn dần theo năm tháng, người tích đức tu thân dần đổi phong tục.",giai:"Mọi việc nên tiến hành từng bước tuần tự, không nên đốt cháy giai đoạn hay vội vàng. Kiên nhẫn đi từng nấc thang vững chắc sẽ đem lại kết quả bền lâu và tốt đẹp.",lines:["Sơ Lục: Chim nhạn bay dần đậu nơi bờ nước, có chút lời chê nhưng chẳng lỗi chi.","Lục Nhị: Chim nhạn lượn bay đậu trên tảng đá, ăn uống no say hưởng trọn yên vui.","Cửu Tam: Chim nhạn bay vượt đậu bờ đất cao, đi xa quên lối phòng ngừa rủi ro.","Lục Tứ: Chim nhạn bay tìm đậu cành cây cong, tìm nơi nương náu bình an tháng ngày.","Cửu Ngũ: Chim nhạn bay cao đậu trên đỉnh đồi, ba năm hòa hợp thỏa nguyện ước mong.","Thượng Cửu: Chim nhạn lưng trời để rơi cánh lông, nêu gương sáng đẹp cho đời soi chung."]},{num:54,name:"Quy Muội",upper:"Chấn",lower:"Đoài",verdict:"hung",guaci:"Gái về nhà chồng làm lẽ chẳng hợp, nôn nóng tiến bước khó được bền lâu.",tuong:"Đầm nước bốc sấm động chẳng yên, người thấu suốt lẽ đời thấy trước suy vi.",giai:"Cảnh ngộ thiếu danh chính ngôn thuận, dễ bị cảm xúc chi phối dẫn đến sai lầm. Chớ nên cưỡng cầu làm việc lớn khi thời thế và vị thế chưa phù hợp.",lines:["Sơ Cửu: Làm lẽ về nhà khập khiễng bước chân, nhún nhường đúng phận vẫn gặp an lành.","Cửu Nhị: Người mù một mắt vẫn cố nhìn xa, giữ lòng son sắt trọn vẹn niềm tin.","Lục Tam: Nôn nóng cầu duyên làm lẽ chờ thời, thiếu sự đoan trang chuốc nỗi bẽ bàng.","Cửu Tứ: Quá lứa nhỡ thì đợi thời duyên mới, chậm trễ đôi chút nhưng rồi cũng xong.","Lục Ngũ: Công chúa gả đi áo xiêm khiêm tốn, giản dị trăng rằm phúc trạch dài lâu.","Thượng Lục: Giỏ đựng trống không dâng lễ chẳng thành, dở dang dang dở chẳng được việc chi."]},{num:55,name:"Phong",upper:"Chấn",lower:"Ly",verdict:"cat",guaci:"Thời vận dồi dào tựa mặt trời đứng bóng, giữ lòng chính trực chớ để lo âu.",tuong:"Sấm chớp cùng vang sáng lòa trời đất, người cầm cân nảy mực phân minh thưởng phạt.",giai:"Vận thế đang ở thời kỳ cực thịnh, công việc phát triển rực rỡ và thuận lợi. Tuy nhiên cần đề phòng nguy cơ sau đỉnh cao, giữ tâm sáng suốt và công bằng trong mọi việc.",lines:["Sơ Cửu: Gặp bạn đồng hành cùng chung chí hướng, mười ngày tương hợp không mắc lỗi lầm.","Lục Nhị: Bức màn che khuất thấy sao giữa trưa, giữ lòng chí thành ắt giải nghi nan.","Cửu Tam: Màn che chắn kín gãy cánh tay phải, khó làm việc lớn tạm thời nhẫn nại.","Cửu Tứ: Trời râm thấy sao gặp người tri kỷ, cùng nhau bước tới gặp điều cát lành.","Lục Ngũ: Chiêu mộ hiền tài rạng rỡ vẻ vang, đón nhận lời khuyên được niềm hoan hỷ.","Thượng Lục: Nhà cao cửa rộng che giấu quạnh hiu, ba năm khép kín chẳng thấy bóng người."]},{num:56,name:"Lữ",upper:"Ly",lower:"Cấn",verdict:"hung",guaci:"Khách tha hương việc nhỏ còn thông, lưu lạc bơ vơ giữ mình cẩn trọng.",tuong:"Ngọn lửa trên núi cháy lan từng đợt, người quân tử thận trọng thưởng phạt chẳng giam lâu.",giai:"Hoàn cảnh phiêu bạt nơi đất khách quê người, thiếu chỗ dựa và nhiều nỗi bất an. Cần giữ thái độ khiêm nhường, hòa nhã với mọi người và chớ nên tranh chấp.",lines:["Sơ Lục: Khách trọ bận tâm chuyện vặt tầm thường, tự chuốc tai vạ rước lấy phiền toái.","Lục Nhị: Đến chốn nhà trọ gặp người trung hậu, tiền túi còn nguyên được lòng mọi người.","Cửu Tam: Đốt phá quán trọ mất kẻ phụ việc, tính tình nóng nảy chuốc lấy hiểm nguy.","Cửu Tứ: Tạm nghỉ bên đường có rìu phòng thân, lòng còn canh cánh chưa được thảnh thơi.","Lục Ngũ: Bắn chim trĩ bay mũi tên rơi rụng, sau được khen ngợi nhận trọn danh thơm.","Thượng Cửu: Chim cháy mất tổ khách cười rồi khóc, ngạo mạn sơ suất đánh mất bò nhà."]},{num:57,name:"Tốn",upper:"Tốn",lower:"Tốn",verdict:"cat",guaci:"Gió thoảng dịu dàng luồn sâu muôn lối, thuận tình đạt ý mưu sự dễ thành.",tuong:"Gió nọ tiếp gió kia thổi đi khắp chốn, người ban truyền mệnh lệnh chăm lo việc đời.",giai:"Nên dùng sự mềm mỏng, khéo léo và khiêm nhường để đối nhân xử thế. Lắng nghe và thấu hiểu lòng người sẽ giúp tháo gỡ bế tắc và đạt được sự đồng thuận.",lines:["Sơ Lục: Tiến thoái dùng dằng lòng dạ chưa quyết, như lính giữ đồn nên có chủ kiến.","Cửu Nhị: Nhún mình nép dưới gầm giường đợi lúc, dùng lời thành tâm tai ách tiêu trừ.","Cửu Tam: Nhún nhường quá mức sinh lòng tủi hờn, thiếu tính tự chủ hối tiếc chẳng nguôi.","Lục Tứ: Hối tiếc tiêu tan săn được muông thú, khéo léo xử thế thu trọn điều may.","Cửu Ngũ: Giữ lòng trung chính chuyển họa thành phúc, trước sau ba ngày mưu sự vẹn toàn.","Thượng Cửu: Cúi mình gầm giường mất rìu phòng thân, quá đỗi nhu nhược tự chuốc hung tai."]},{num:58,name:"Đoài",upper:"Đoài",lower:"Đoài",verdict:"cat",guaci:"Đầm nước vui tươi thuận hòa gắn kết, giữ dạ chân thành gặp điều lợi ích.",tuong:"Đầm nước liền nhau bồi đắp cho nhau, bạn bè bè bạn cùng bàn đạo lý trau dồi tri thức.",giai:"Thời vận hòa thuận vui vẻ, các mối quan hệ giao tiếp cởi mở và ấm áp. Hãy lấy lòng chân thật đối đãi bạn bè, chia sẻ niềm vui nhưng tránh sa đà vào lời nịnh hót.",lines:["Sơ Cửu: Vui vẻ hòa nhã tâm thế thanh thản, sống đời thanh bạch không mắc lỗi lầm.","Cửu Nhị: Chân thành gắn kết niềm vui lan tỏa, giữ dạ thủy chung hối tiếc tiêu tan.","Lục Tam: Tìm kiếm niềm vui nơi chốn phù phiếm, a dua đua đòi chuốc lấy tai ương.","Cửu Tứ: Đắn đo lựa chọn niềm vui thanh cao, dứt khoát xa lánh điều ác được an.","Cửu Ngũ: Tin kẻ xảo quyệt lòng dạ bấp bênh, cẩn trọng phòng ngừa giữ mình khỏi vạ.","Thượng Lục: Dẫn dắt người ta vào chốn vui chơi, ham mê lạc lối chẳng có điều hay."]},{num:59,name:"Hoán",upper:"Tốn",lower:"Khảm",verdict:"trung",guaci:"Gió lướt mặt nước mây tan băng giá, cúng tế thần linh vượt qua sông lớn.",tuong:"Gió thổi trên mặt nước sóng gợn tan mau, người lập đền miếu tế lễ tổ tiên.",giai:"Thời kỳ xua tan bế tắc và ngăn cách, lòng người dần cởi mở và hàn gắn lại. Cần người có uy tín đứng ra gắn kết tập thể, giải tỏa mâu thuẫn để cùng vượt khó khăn.",lines:["Sơ Lục: Nhờ ngựa khỏe kéo cứu giúp kịp thời, nhanh chân thoát hiểm gặp điềm cát lành.","Cửu Nhị: Chạy đến nương tựa nơi chốn an toàn, lòng thanh thản lại hối tiếc tiêu tan.","Lục Tam: Tan biến cái tôi lo cho thiên hạ, quên mình vì người chẳng chuốc âu lo.","Lục Tứ: Phá tan bè phái mở rộng tầm nhìn, người thường khó thấu điều đại cát tường.","Cửu Ngũ: Tiếng hô vang dậy ban phát của công, đoàn kết muôn người không vướng lỗi chi.","Thượng Cửu: Máu tan tai hết tránh xa nguy nan, đi xa khỏi hiểm hưởng trọn bình an."]},{num:60,name:"Tiết",upper:"Khảm",lower:"Đoài",verdict:"trung",guaci:"Tiết độ chừng mực ắt việc hanh thông, quá đỗi khắt khe chẳng bền lâu dài.",tuong:"Đầm nước giữ nước theo khuôn chừng mực, người đặt ra chuẩn mực lễ nghi đức độ.",giai:"Cần giữ chừng mực trong lời nói, chi tiêu và hành động để bảo toàn nguồn lực. Đặt ra giới hạn hợp lý giúp tránh lãng phí, nhưng chớ nên quá hà khắc làm mất lòng người.",lines:["Sơ Cửu: Chẳng bước ra khỏi cổng ngõ sân nhà, biết giữ gìn mình không mắc lỗi lầm.","Cửu Nhị: Không bước ra khỏi cửa sân đón thời, bỏ lỡ cơ hội chuốc lấy điều hung.","Lục Tam: Không biết tiết chế buông thả phóng túng, than vãn muộn màng trách được ai đây.","Lục Tứ: Bình thản tiết độ theo lẽ tự nhiên, thuận hòa êm đẹp việc ắt hanh thông.","Cửu Ngũ: Tiết độ ngọt ngào muôn người mến phục, tiến bước hành sự gặp điềm cát lành.","Thượng Lục: Khắt khe cay đắng tự trói buộc mình, cố chấp giữ mãi chuốc lấy ăn năn."]},{num:61,name:"Trung Phu",upper:"Tốn",lower:"Đoài",verdict:"cat",guaci:"Lòng thành cảm hóa muông thú cá heo, vượt qua sông lớn thuận buồm xuôi gió.",tuong:"Gió thổi trên mặt đầm nước xao động, người thẩm xét vụ việc tha thứ khoan dung.",giai:"Sự chân thành và uy tín là chìa khóa mở lối thành công, tạo nên sức mạnh gắn kết sâu sắc. Hãy đối đãi bằng cái tâm trung thực, không dối gạt thì mọi khó khăn đều hóa giải.",lines:["Sơ Cửu: Giữ tâm bình thản hưởng trọn an lành, nảy sinh toan tính lòng chẳng yên ổn.","Cửu Nhị: Hạc kêu trong bóng râm con liền họa lại, có chén rượu ngon cùng bạn sẻ chia.","Lục Tam: Gặp kẻ đối đầu khi khóc khi cười, tâm tình bất định chẳng được yên vui.","Lục Tứ: Trăng sắp tròn vành ngựa lẻ đôi bạn, bỏ thói kết bè không mắc lỗi chi.","Cửu Ngũ: Lòng thành gắn kết siết chặt niềm tin, đức độ lan tỏa không chút tỳ vết.","Thượng Cửu: Tiếng gà gáy vọng tận chín tầng mây, lời suông thiếu thực chuốc nỗi ngậm ngùi."]},{num:62,name:"Tiểu Quá",upper:"Chấn",lower:"Cấn",verdict:"trung",guaci:"Vượt mức đôi chút việc nhỏ thì hay, chim bay chớ vội bay cao mỏi cánh.",tuong:"Sấm vang trên núi âm thanh vang xa, người xử sự khiêm nhường chi tiêu giản dị.",giai:"Chỉ nên làm những việc nhỏ, cẩn thận tỉ mỉ hơn bình thường một chút để tránh sơ suất. Không nên ôm đồm việc lớn hay mạo hiểm vượt quá khả năng bản thân.",lines:["Sơ Lục: Chim non vội vã bay lượn trên cao, chưa đủ lông cánh chuốc lấy tai ương.","Lục Nhị: Đi qua ông nội gặp được bà nội, việc nhỏ thuận lợi không vướng lỗi lầm.","Cửu Tam: Chẳng chịu phòng ngừa lơ là cảnh giác, kẻ xấu thừa cơ chuốc lấy điều hung.","Cửu Tứ: Nhường nhịn tránh né không chút lỗi lầm, tiến bước mạo hiểm chi bằng dừng chân.","Lục Ngũ: Mây dày không mưa từ chốn tây thành, bắn trúng chim muông nơi hang sâu kín.","Thượng Lục: Bay cao quá mức sa lưới chim rơi, ngạo mạn làm càn gặp cảnh hiểm nguy."]},{num:63,name:"Ký Tế",upper:"Khảm",lower:"Ly",verdict:"cat",guaci:"Việc lớn đã thành buổi đầu tốt đẹp, cẩn trọng giữ gìn kẻo cuối rối ren.",tuong:"Nước ở trên lửa nấu chín thức ăn, người phòng ngừa tai họa trước khi nảy sinh.",giai:"Mọi sự đã tạm thời ổn định, công việc gặt hái kết quả viên mãn như ý nguyện. Tuy nhiên đỉnh cao thường đi liền thoái trào, cần duy trì trật tự và không được chủ quan lơ là.",lines:["Sơ Cửu: Hãm phanh kéo bánh xe ướt đuôi cáo, thận trọng ban đầu không mắc lỗi chi.","Lục Nhị: Đánh rơi khăn màn che mặt lúc đi, chẳng cần tìm kiếm bảy ngày lại thấy.","Cửu Tam: Đem quân phạt quỷ ba năm mệt nhoài, người tài vất vả chớ cậy tiểu nhân.","Lục Tứ: Áo rách lấy giẻ nhét kín lỗ hổng, suốt ngày cẩn mật đề phòng rủi ro.","Cửu Ngũ: Mổ trâu cúng bái chẳng bằng cúng chay, lòng thành giản dị hưởng phúc dài lâu.","Thượng Lục: Lội qua con nước ướt cả mái đầu, lơ đễnh chủ quan chuốc lấy tai nguy."]},{num:64,name:"Vị Tế",upper:"Ly",lower:"Khảm",verdict:"trung",guaci:"Việc chưa xong xuôi cáo nhỏ lội sông, ướt sũng đuôi dài chưa tới bến bờ.",tuong:"Lửa bốc lên cao nước chảy xuống thấp, người thận trọng phân biệt muôn vật yên vui.",giai:"Giai đoạn chuyển giao chuẩn bị cho một chu kỳ mới, công việc còn dang dở chưa hoàn tất. Đòi hỏi sự kiên nhẫn, chuẩn bị kỹ lưỡng và thận trọng từng bước để đi đến đích cuối.",lines:["Sơ Lục: Cáo nhỏ lội sông ướt sũng đuôi dài, hấp tấp qua bến khó nỗi vẹn toàn.","Cửu Nhị: Hãm giữ bánh xe chớ vội tiến nhanh, kiên trì nhẫn nại điềm lành theo sau.","Lục Tam: Chưa thể vượt sông nôn nóng tiến công, tạm dừng phòng thủ tránh điều gian nguy.","Cửu Tứ: Giữ vững chính tâm đánh dẹp gian nan, ba năm gắng sức công thành danh toại.","Lục Ngũ: Ánh sáng quân tử rạng rỡ cát tường, giữ trọn niềm tin đón chào vận mới.","Thượng Cửu: Uống rượu mừng vui ướt cả mái đầu, giữ mình chừng mực chớ say quá đà."]}];"undefined"!=typeof window&&(window.YIJING_HEXAGRAMS=YIJING_HEXAGRAMS),"undefined"!=typeof globalThis&&(globalThis.YIJING_HEXAGRAMS=YIJING_HEXAGRAMS),"undefined"!=typeof module&&module.exports&&(module.exports={YIJING_HEXAGRAMS:YIJING_HEXAGRAMS});